pattern=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
grid=[[0]*30 for _ in range(30)]
for tr in range(4):
 for tc in range(4):
  y,x=tr*7,tc*7
  for dy in range(1,6):
   for dx in range(1,6): grid[y+dy][x+dx]=4
  for dy in range(2,5):
   for dx in range(2,5): grid[y+dy][x+dx]=pattern[tr][tc]
# connect same special pattern classes through empty gaps, with thickness equal to 3x3 patches
# horizontal 3 at tile rows 0,2 from tile cols 0 to 3; 8 at tile rows 1,3 from cols1 to2
for tr, color, c1, c2 in [(0,3,0,3),(2,3,0,3),(1,8,1,2),(3,8,1,2)]:
 y=tr*7+2
 # replace zeros only in gap columns between the relevant tile locations
 for tc in range(c1,c2):
  for r in range(y,y+3):
   for c in range(tc*7+6,tc*7+8):
    if grid[r][c]==0: grid[r][c]=color
# vertical 3 at tile cols0,3 between rows0..2; 8 at cols1,2 between rows1..3
for tc,color,r1,r2 in [(0,3,0,2),(3,3,0,2),(1,8,1,3),(2,8,1,3)]:
 x=tc*7+2
 for tr in range(r1,r2):
  for r in range(tr*7+6,tr*7+8):
   for c in range(x,x+3):
    if grid[r][c]==0: grid[r][c]=color
print('\n'.join(' '.join(map(str,row)) for row in grid))
